-- IMAP is read-only. Parsed MIME/encryption are trusted Node boundaries, never caller URLs.
CREATE TABLE email_inbound_accounts (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,name text NOT NULL,host text NOT NULL,port integer NOT NULL,transport text NOT NULL CHECK(transport IN('tls','local_fixture')),folder text NOT NULL,smtp_channel_id uuid NOT NULL,enabled boolean NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),credentials_encrypted text,username_masked text NOT NULL,uidvalidity text,last_uid text,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,smtp_channel_id) REFERENCES channels(tenant_id,id),CHECK((transport='tls' AND port=993) OR(transport='local_fixture' AND host='127.0.0.1' AND port=4112)),CHECK(NOT enabled OR credentials_encrypted IS NOT NULL)
);
CREATE TABLE email_inbound_acquisitions (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,account_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,request jsonb NOT NULL,account_version bigint NOT NULL,config_hash text NOT NULL,folder text NOT NULL,state text NOT NULL CHECK(state IN('fetching','ready','unknown','failed','abandoned')),preview_id uuid,uidvalidity text,uidnext text,scanned_through_uid text,error_code text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,id,account_id),UNIQUE(tenant_id,client_key),FOREIGN KEY(tenant_id,account_id) REFERENCES email_inbound_accounts(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id)
);
CREATE UNIQUE INDEX email_inbound_fetching_account ON email_inbound_acquisitions(tenant_id,account_id) WHERE state='fetching';
CREATE TABLE email_inbound_sources (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,account_id uuid NOT NULL,folder text NOT NULL,uidvalidity text NOT NULL,uid text NOT NULL,raw_sha256 text NOT NULL CHECK(raw_sha256~'^[a-f0-9]{64}$'),raw_bytes integer NOT NULL CHECK(raw_bytes BETWEEN 1 AND 4194304),headers jsonb NOT NULL,text_body text NOT NULL CHECK(char_length(text_body)<=20000),attachments jsonb NOT NULL CHECK(jsonb_typeof(attachments)='array' AND jsonb_array_length(attachments)<=10),content_encrypted text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,account_id,folder,uidvalidity,uid),FOREIGN KEY(tenant_id,account_id) REFERENCES email_inbound_accounts(tenant_id,id),CHECK(uid~'^[1-9][0-9]{0,9}$' AND uidvalidity~'^[1-9][0-9]{0,9}$')
);
CREATE TABLE email_inbound_previews (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,acquisition_id uuid NOT NULL,account_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,scope_hash text NOT NULL CHECK(scope_hash~'^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '15 minutes',
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,acquisition_id),FOREIGN KEY(tenant_id,acquisition_id,account_id) REFERENCES email_inbound_acquisitions(tenant_id,id,account_id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),CHECK(jsonb_typeof(payload->'rows')='array' AND jsonb_array_length(payload->'rows')<=50 AND octet_length(payload::text)<=67108864)
);
ALTER TABLE email_inbound_acquisitions ADD FOREIGN KEY(tenant_id,preview_id) REFERENCES email_inbound_previews(tenant_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE email_inbound_messages (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,source_id uuid NOT NULL,account_id uuid NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),state text NOT NULL DEFAULT 'unassigned' CHECK(state IN('unassigned','bound')),order_id uuid,thread_id uuid,core_message_id uuid,binding_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,source_id),FOREIGN KEY(tenant_id,source_id) REFERENCES email_inbound_sources(tenant_id,id),FOREIGN KEY(tenant_id,account_id) REFERENCES email_inbound_accounts(tenant_id,id),FOREIGN KEY(tenant_id,order_id,thread_id) REFERENCES customer_message_threads(tenant_id,order_id,id),FOREIGN KEY(tenant_id,core_message_id) REFERENCES customer_messages(tenant_id,id),CHECK((state='unassigned' AND num_nonnulls(order_id,thread_id,core_message_id,binding_id)=0) OR(state='bound' AND num_nonnulls(order_id,thread_id,core_message_id,binding_id)=4))
);
CREATE TABLE email_inbound_bindings (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,message_id uuid NOT NULL,order_id uuid NOT NULL,thread_id uuid NOT NULL,core_message_id uuid NOT NULL,order_version bigint NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,message_id),UNIQUE(tenant_id,core_message_id),FOREIGN KEY(tenant_id,message_id) REFERENCES email_inbound_messages(tenant_id,id),FOREIGN KEY(tenant_id,order_id,thread_id) REFERENCES customer_message_threads(tenant_id,order_id,id),FOREIGN KEY(tenant_id,core_message_id) REFERENCES customer_messages(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id)
);
ALTER TABLE email_inbound_messages ADD FOREIGN KEY(tenant_id,binding_id) REFERENCES email_inbound_bindings(tenant_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE email_inbound_reply_previews (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,message_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,request jsonb NOT NULL,scope_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '15 minutes',
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),FOREIGN KEY(tenant_id,message_id) REFERENCES email_inbound_messages(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),CHECK(scope_hash~'^[a-f0-9]{64}$')
);
CREATE TABLE email_inbound_replies (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,preview_id uuid NOT NULL,message_id uuid NOT NULL,batch_id uuid NOT NULL,email_message_id uuid NOT NULL,job_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),UNIQUE(tenant_id,preview_id),UNIQUE(tenant_id,batch_id),UNIQUE(tenant_id,email_message_id),FOREIGN KEY(tenant_id,preview_id) REFERENCES email_inbound_reply_previews(tenant_id,id),FOREIGN KEY(tenant_id,message_id) REFERENCES email_inbound_messages(tenant_id,id),FOREIGN KEY(tenant_id,batch_id) REFERENCES email_batches(tenant_id,id),FOREIGN KEY(tenant_id,email_message_id) REFERENCES email_messages(tenant_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES jobs(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id)
);
CREATE TABLE email_inbound_operations (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,kind text NOT NULL,target_id uuid,request_hash text NOT NULL CHECK(request_hash~'^[a-f0-9]{64}$'),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,kind,client_key),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id)
);
CREATE TABLE email_inbound_admissions (
 tenant_id uuid NOT NULL,transaction_id xid8 NOT NULL,operation_id uuid NOT NULL,kind text NOT NULL,actor_id uuid NOT NULL,api_key_id uuid,target_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,transaction_id,operation_id),FOREIGN KEY(tenant_id,operation_id) REFERENCES email_inbound_operations(tenant_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX email_inbound_account_page ON email_inbound_accounts(tenant_id,id);
CREATE INDEX email_inbound_acquisition_page ON email_inbound_acquisitions(tenant_id,account_id,id);
CREATE INDEX email_inbound_message_page ON email_inbound_messages(tenant_id,state,id);
CREATE INDEX email_inbound_reply_page ON email_inbound_replies(tenant_id,message_id,id);
ALTER TABLE customer_messages DROP CONSTRAINT customer_messages_kind_check;
ALTER TABLE customer_messages ADD CHECK(kind IN('buyer','reply','note','email'));
ALTER TABLE customer_messages DROP CONSTRAINT customer_messages_body_check;
ALTER TABLE customer_messages ADD CHECK((kind='email' AND char_length(body) BETWEEN 0 AND 20000) OR(kind<>'email' AND char_length(body) BETWEEN 1 AND 4000));
-- Email is staff-only; binder is actor_id (received_by), not the untrusted RFC author.
ALTER TABLE email_batches ALTER COLUMN template_id DROP NOT NULL;
ALTER TABLE email_batches ALTER COLUMN template_version DROP NOT NULL;
ALTER TABLE email_batches ADD COLUMN inbound_reply_preview_id uuid;
ALTER TABLE email_batches ADD COLUMN inbound_api_key_id uuid;
ALTER TABLE email_batches ADD FOREIGN KEY(tenant_id,inbound_reply_preview_id) REFERENCES email_inbound_reply_previews(tenant_id,id);
ALTER TABLE email_batches ADD FOREIGN KEY(tenant_id,inbound_api_key_id) REFERENCES api_keys(tenant_id,id);
ALTER TABLE email_batches ADD CHECK((inbound_reply_preview_id IS NULL AND template_id IS NOT NULL AND template_version IS NOT NULL AND inbound_api_key_id IS NULL) OR(inbound_reply_preview_id IS NOT NULL AND template_id IS NULL AND template_version IS NULL AND mode='smtp' AND automation_run_id IS NULL AND automation_schedule_run_id IS NULL AND order_batch_id IS NULL));
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['email_inbound_accounts','email_inbound_acquisitions','email_inbound_sources','email_inbound_previews','email_inbound_messages','email_inbound_bindings','email_inbound_reply_previews','email_inbound_replies','email_inbound_operations','email_inbound_admissions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',rel);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',rel);
 EXECUTE format('CREATE POLICY tenant_scope ON %I TO dyna_app USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',rel);
 EXECUTE format('CREATE POLICY owner_scope ON %I TO %I USING(true) WITH CHECK(true)',rel,current_user);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,dyna_app',rel);
END LOOP;END $$;
CREATE FUNCTION email_inbound_installed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$SELECT EXISTS(SELECT 1 FROM public.migrations WHERE name='141_email_inbound')$$;
CREATE FUNCTION email_inbound_hash(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex')$$;
CREATE FUNCTION email_inbound_access(uid uuid,kid uuid,writing boolean,pin boolean,manage boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;r text;k public.api_keys;valid boolean:=true;rd boolean:=true;wr boolean:=true;mg boolean:=true;BEGIN
 IF pin THEN SELECT role INTO r FROM public.memberships WHERE tenant_id=t AND user_id=uid FOR SHARE;ELSE SELECT role INTO r FROM public.memberships WHERE tenant_id=t AND user_id=uid;END IF;
 IF kid IS NOT NULL THEN
 IF pin THEN SELECT * INTO k FROM public.api_keys WHERE(tenant_id,id,user_id)=(t,kid,uid) FOR SHARE;ELSE SELECT * INTO k FROM public.api_keys WHERE(tenant_id,id,user_id)=(t,kid,uid);END IF;
 valid:=k.id IS NOT NULL AND k.revoked_at IS NULL AND k.expires_at>clock_timestamp();rd:=valid AND 'communications:read'=ANY(k.scopes);wr:=rd AND 'communications:write'=ANY(k.scopes);mg:=wr AND 'integrations:write'=ANY(k.scopes);
 END IF;
 RETURN jsonb_build_object('role',r,'key_valid',valid,'allowed',coalesce(rd AND r IN('admin','operator','viewer') AND(NOT writing OR(wr AND r IN('admin','operator'))) AND(NOT manage OR(mg AND r='admin')),false),'can_write',coalesce(wr AND r IN('admin','operator'),false),'can_manage_accounts',coalesce(mg AND r='admin',false),'can_order_read',kid IS NULL OR coalesce('orders:read'=ANY(k.scopes),false));
END $$;
CREATE FUNCTION email_inbound_begin(oid uuid,op text,rid uuid,uid uuid,kid uuid,ck uuid,h text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;old public.email_inbound_operations;BEGIN
 PERFORM public.email_inbound_require(uid,kid,true,false,op IN('account_create','account_update'));PERFORM public.email_inbound_lock();
 IF op IS NULL OR op NOT IN('account_create','account_update','fetch_begin','fetch_finish','reconcile','import','bind','reply_preview','reply_queue') OR ck IS NULL OR h IS NULL OR h!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Nieprawidłowa operacja odbioru email' USING ERRCODE='23514';END IF;
 IF op IN('bind','reply_preview','reply_queue') AND(public.email_inbound_access(uid,kid,true,false)->'can_order_read') IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Brak aktualnego uprawnienia odbioru email' USING ERRCODE='23514';END IF;
 SELECT * INTO old FROM public.email_inbound_operations WHERE tenant_id=t AND kind=op AND client_key=ck;
 IF old.id IS NOT NULL THEN IF(old.actor_id,old.api_key_id,old.target_id,old.request_hash) IS DISTINCT FROM(uid,kid,rid,h) THEN RAISE EXCEPTION 'Klucz email ma inny zakres' USING ERRCODE='23514';END IF;RETURN jsonb_build_object('operation_id',old.id,'reused',true,'result',old.result);END IF;
 INSERT INTO public.email_inbound_admissions(tenant_id,transaction_id,operation_id,kind,actor_id,api_key_id,target_id,client_key,request_hash) VALUES(t,pg_current_xact_id(),oid,op,uid,kid,rid,ck,h);
 RETURN jsonb_build_object('operation_id',oid,'reused',false);
END $$;
CREATE FUNCTION email_inbound_store(oid uuid,ck uuid,h text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;ad public.email_inbound_admissions;a public.email_inbound_accounts;ac public.email_inbound_acquisitions;pv public.email_inbound_previews;s public.email_inbound_sources;m public.email_inbound_messages;rp public.email_inbound_reply_previews;ch public.channels;o public.orders;cm public.customer_messages;x jsonb;rows_json jsonb:='[]';result jsonb;entity uuid;mid uuid;bid uuid;eid uuid;jid uuid;new_count integer:=0;dup_count integer:=0;raw_total bigint:=0;attachment_total bigint:=0;row_index integer:=0;payload jsonb;BEGIN
 SELECT * INTO ad FROM public.email_inbound_admissions WHERE tenant_id=t AND transaction_id=pg_current_xact_id() AND operation_id=oid;IF ad.operation_id IS NULL THEN RAISE EXCEPTION 'Brak bieżącej zgody email' USING ERRCODE='23514';END IF;
 PERFORM public.email_inbound_require(ad.actor_id,ad.api_key_id,true,false,ad.kind IN('account_create','account_update'));
 IF(ad.client_key,ad.request_hash) IS DISTINCT FROM(ck,h) THEN RAISE EXCEPTION 'Operacja email ma inny klucz lub treść' USING ERRCODE='23514';END IF;
 IF ad.kind IN('bind','reply_preview','reply_queue') AND(public.email_inbound_access(ad.actor_id,ad.api_key_id,true,false)->'can_order_read') IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Brak aktualnego uprawnienia odbioru email' USING ERRCODE='23514';END IF;
 IF ad.kind IN('account_create','account_update') THEN
  IF ad.kind='account_update' THEN SELECT * INTO a FROM public.email_inbound_accounts WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF a.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono konta' USING ERRCODE='P0002';END IF;IF a.version::text IS DISTINCT FROM b->>'version' THEN RAISE EXCEPTION 'Konto IMAP zmieniło się' USING ERRCODE='23514';END IF;
  IF EXISTS(SELECT 1 FROM public.email_inbound_acquisitions WHERE tenant_id=t AND account_id=a.id AND state IN('fetching','unknown')) THEN RAISE EXCEPTION 'Najpierw rozstrzygnij rozpoczęty odczyt IMAP' USING ERRCODE='23514';END IF;END IF;
  SELECT * INTO ch FROM public.channels WHERE tenant_id=t AND id=(b->>'smtp_channel_id')::uuid;IF ch.id IS NULL OR ch.provider<>'smtp' THEN RAISE EXCEPTION 'Wymagane własne konto SMTP' USING ERRCODE='23514';END IF;
  entity:=CASE WHEN ad.kind='account_create' THEN(b->>'id')::uuid ELSE a.id END;
  IF ad.kind='account_create' THEN INSERT INTO public.email_inbound_accounts(id,tenant_id,name,host,port,transport,folder,smtp_channel_id,enabled,credentials_encrypted,username_masked) VALUES(entity,t,b->>'name',b->>'host',(b->>'port')::integer,b->>'transport',b->>'folder',ch.id,(b->>'enabled')::boolean,b->>'credentials_encrypted',b->>'username_masked') RETURNING * INTO a;
  ELSE UPDATE public.email_inbound_accounts SET name=b->>'name',host=b->>'host',port=(b->>'port')::integer,transport=b->>'transport',folder=b->>'folder',smtp_channel_id=ch.id,enabled=(b->>'enabled')::boolean,credentials_encrypted=CASE WHEN b->>'credentials_action'='keep' THEN a.credentials_encrypted ELSE b->>'credentials_encrypted' END,username_masked=CASE WHEN b->>'credentials_action'='keep' THEN a.username_masked ELSE b->>'username_masked' END,version=version+1,uidvalidity=NULL,last_uid=NULL,updated_at=clock_timestamp() WHERE tenant_id=t AND id=entity RETURNING * INTO a;END IF;
  result:=jsonb_build_object('account',public.email_inbound_account_head(a));
 ELSIF ad.kind='fetch_begin' THEN
  SELECT * INTO a FROM public.email_inbound_accounts WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF a.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono konta' USING ERRCODE='P0002';END IF;
  IF NOT a.enabled OR a.credentials_encrypted IS NULL OR a.version::text IS DISTINCT FROM b->'request'->>'account_version' OR public.email_inbound_hash(to_jsonb(a)-ARRAY['uidvalidity','last_uid','updated_at']) IS DISTINCT FROM b->>'config_hash' THEN RAISE EXCEPTION 'Konto IMAP wymaga świeżej wersji' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(b->'request') IS DISTINCT FROM 'object' OR b->'request'->'confirmed_read' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(b->'request'->'limit') IS DISTINCT FROM 'number' OR coalesce(b->'request'->>'limit','')!~'^[0-9]+$' THEN RAISE EXCEPTION 'Nieprawidłowe żądanie IMAP' USING ERRCODE='23514';END IF;
  IF(b->'request'->>'limit')::bigint NOT BETWEEN 1 AND 50 OR(b->'request'->>'after_uid' IS NOT NULL AND b->'request'->>'after_uid'!~'^[1-9][0-9]{0,9}$') OR(b->'request'->>'expected_uidvalidity' IS NOT NULL AND b->'request'->>'expected_uidvalidity'!~'^[1-9][0-9]{0,9}$') THEN RAISE EXCEPTION 'Nieprawidłowe żądanie IMAP' USING ERRCODE='23514';END IF;
  IF coalesce((b->'request'->>'after_uid')::bigint,0)>4294967295 OR coalesce((b->'request'->>'expected_uidvalidity')::bigint,0)>4294967295 THEN RAISE EXCEPTION 'Nieprawidłowe żądanie IMAP' USING ERRCODE='23514';END IF;
  IF b->'request'->>'expected_uidvalidity' IS NULL AND b->'request'->>'after_uid' IS NOT NULL THEN RAISE EXCEPTION 'Nowa przestrzeń UID wymaga odczytu od początku' USING ERRCODE='23514';END IF;
  IF EXISTS(SELECT 1 FROM public.email_inbound_acquisitions WHERE tenant_id=t AND account_id=a.id AND state IN('fetching','unknown')) THEN RAISE EXCEPTION 'Najpierw rozstrzygnij rozpoczęty odczyt IMAP' USING ERRCODE='23514';END IF;
  entity:=(b->>'id')::uuid;INSERT INTO public.email_inbound_acquisitions(id,tenant_id,account_id,actor_id,api_key_id,client_key,request_hash,request,account_version,config_hash,folder,state) VALUES(entity,t,a.id,ad.actor_id,ad.api_key_id,ck,h,b->'request',a.version,b->>'config_hash',a.folder,'fetching') RETURNING * INTO ac;result:=jsonb_build_object('acquisition_id',ac.id);
 ELSIF ad.kind='fetch_finish' THEN
  SELECT * INTO ac FROM public.email_inbound_acquisitions WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF ac.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono odczytu' USING ERRCODE='P0002';END IF;
  IF(ac.actor_id,ac.api_key_id) IS DISTINCT FROM(ad.actor_id,ad.api_key_id) OR ac.state<>'fetching' THEN RAISE EXCEPTION 'Odczyt IMAP nie jest bieżący' USING ERRCODE='23514';END IF;
  SELECT * INTO a FROM public.email_inbound_accounts WHERE tenant_id=t AND id=ac.account_id FOR UPDATE;
  IF NOT a.enabled OR a.version<>ac.account_version OR public.email_inbound_hash(to_jsonb(a)-ARRAY['uidvalidity','last_uid','updated_at']) IS DISTINCT FROM ac.config_hash THEN RAISE EXCEPTION 'Konto IMAP zmieniło się podczas odczytu' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(b->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'sources')>50 OR b->>'uidvalidity' IS NULL OR b->>'uidvalidity'!~'^[1-9][0-9]{0,9}$' OR(ac.request->>'expected_uidvalidity' IS NOT NULL AND ac.request->>'expected_uidvalidity' IS DISTINCT FROM b->>'uidvalidity') THEN RAISE EXCEPTION 'Nieprawidłowy pełny podgląd IMAP' USING ERRCODE='23514';END IF;
  IF b->>'uidnext' IS NULL OR b->>'uidnext'!~'^[1-9][0-9]{0,9}$' OR b->>'scanned_through_uid' IS NULL OR b->>'scanned_through_uid'!~'^(0|[1-9][0-9]{0,9})$' THEN RAISE EXCEPTION 'Nieprawidłowe okno UID' USING ERRCODE='23514';END IF;
  IF coalesce((ac.request->>'after_uid')::bigint,0)>0 AND coalesce((ac.request->>'after_uid')::bigint,0)>=(b->>'uidnext')::bigint THEN RAISE EXCEPTION 'Nieprawidłowe okno UID' USING ERRCODE='23514';END IF;
  IF (b->>'uidvalidity')::bigint>4294967295 OR(b->>'uidnext')::bigint>4294967295 OR(b->>'scanned_through_uid')::bigint IS DISTINCT FROM greatest(coalesce((ac.request->>'after_uid')::bigint,0),least(coalesce((ac.request->>'after_uid')::bigint,0)+(ac.request->>'limit')::integer,(b->>'uidnext')::bigint-1)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(b->'sources') z WHERE z->>'uid' IS NULL OR z->>'uid'!~'^[1-9][0-9]{0,9}$') THEN RAISE EXCEPTION 'Nieprawidłowe okno UID' USING ERRCODE='23514';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'sources') z WHERE(z->>'uid')::bigint<=coalesce((ac.request->>'after_uid')::bigint,0) OR(z->>'uid')::bigint>(b->>'scanned_through_uid')::bigint) OR(SELECT count(*) FROM jsonb_array_elements(b->'sources'))<>(SELECT count(DISTINCT z->>'uid') FROM jsonb_array_elements(b->'sources') z) THEN RAISE EXCEPTION 'Źródła nie odpowiadają unikalnemu oknu UID' USING ERRCODE='23514';END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(b->'sources') LOOP
   IF jsonb_typeof(x->'headers') IS DISTINCT FROM 'object' OR x->>'text' IS NULL OR x->>'raw_sha256' IS NULL OR x->>'raw_sha256'!~'^[a-f0-9]{64}$' OR jsonb_typeof(x->'raw_bytes') IS DISTINCT FROM 'number' OR NOT((x->>'raw_bytes')::bigint BETWEEN 1 AND 4194304) OR jsonb_typeof(x->'attachments') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'attachments')>10 OR char_length(x->>'text')>20000 OR x->>'content_encrypted' IS NULL THEN RAISE EXCEPTION 'Nieprawidłowy zamrożony MIME' USING ERRCODE='23514';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(x->'attachments') f WHERE jsonb_typeof(f->'bytes') IS DISTINCT FROM 'number' OR NOT((f->>'bytes')::bigint BETWEEN 0 AND 2097152) OR f->>'sha256' IS NULL OR f->>'sha256'!~'^[a-f0-9]{64}$') OR(SELECT coalesce(sum((f->>'bytes')::bigint),0) FROM jsonb_array_elements(x->'attachments') f)>4194304 THEN RAISE EXCEPTION 'Załączniki MIME przekraczają limit' USING ERRCODE='23514';END IF;
   SELECT * INTO s FROM public.email_inbound_sources WHERE(tenant_id,account_id,folder,uidvalidity,uid)=(t,a.id,ac.folder,b->>'uidvalidity',x->>'uid');
   IF s.id IS NULL THEN INSERT INTO public.email_inbound_sources(id,tenant_id,account_id,folder,uidvalidity,uid,raw_sha256,raw_bytes,headers,text_body,attachments,content_encrypted) VALUES((x->>'id')::uuid,t,a.id,ac.folder,b->>'uidvalidity',x->>'uid',x->>'raw_sha256',(x->>'raw_bytes')::integer,x->'headers',x->>'text',x->'attachments',x->>'content_encrypted') RETURNING * INTO s;
   ELSIF(s.raw_sha256,s.raw_bytes,s.headers,s.text_body,s.attachments) IS DISTINCT FROM(x->>'raw_sha256',(x->>'raw_bytes')::integer,x->'headers',x->>'text',x->'attachments') THEN RAISE EXCEPTION 'Tożsamość UID ma inne bajty MIME' USING ERRCODE='23514';END IF;
   SELECT id INTO mid FROM public.email_inbound_messages WHERE tenant_id=t AND source_id=s.id;
   rows_json:=rows_json||jsonb_build_array(jsonb_build_object('index',row_index,'source_id',s.id,'uid',s.uid,'raw_sha256',s.raw_sha256,'raw_bytes',s.raw_bytes,'headers',s.headers,'text',s.text_body,'attachments',s.attachments,'duplicate',mid IS NOT NULL,'message_id',mid));row_index:=row_index+1;raw_total:=raw_total+s.raw_bytes;attachment_total:=attachment_total+(SELECT coalesce(sum((f->>'bytes')::bigint),0) FROM jsonb_array_elements(s.attachments) f);
  END LOOP;
  IF raw_total>67108864 THEN RAISE EXCEPTION 'Podgląd MIME przekracza 64 MiB' USING ERRCODE='23514';END IF;
  entity:=(b->>'preview_id')::uuid;payload:=jsonb_build_object('account_id',a.id,'account_version',a.version::text,'client_key',ac.client_key,'folder',ac.folder,'uidvalidity',b->>'uidvalidity','uidnext',b->>'uidnext','scanned_through_uid',b->>'scanned_through_uid','after_uid',ac.request->'after_uid','rows',rows_json,'summary',jsonb_build_object('rows',row_index,'new',(SELECT count(*) FROM jsonb_array_elements(rows_json) r WHERE r->'duplicate'='false'::jsonb),'duplicates',(SELECT count(*) FROM jsonb_array_elements(rows_json) r WHERE r->'duplicate'='true'::jsonb),'raw_bytes',raw_total,'attachment_bytes',attachment_total));
  INSERT INTO public.email_inbound_previews(id,tenant_id,acquisition_id,account_id,actor_id,api_key_id,scope_hash,payload) VALUES(entity,t,ac.id,a.id,ad.actor_id,ad.api_key_id,public.email_inbound_hash(payload),payload);
  UPDATE public.email_inbound_acquisitions SET state='ready',preview_id=entity,uidvalidity=b->>'uidvalidity',uidnext=b->>'uidnext',scanned_through_uid=b->>'scanned_through_uid',updated_at=clock_timestamp() WHERE tenant_id=t AND id=ac.id;result:=jsonb_build_object('acquisition_id',ac.id,'preview_id',entity);
 ELSIF ad.kind='reconcile' THEN
  SELECT * INTO ac FROM public.email_inbound_acquisitions WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF ac.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono odczytu' USING ERRCODE='P0002';END IF;
  IF ac.actor_id<>ad.actor_id OR ac.api_key_id IS DISTINCT FROM ad.api_key_id OR ac.state NOT IN('fetching','unknown','failed') OR b->'confirmed_abandon' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Nie można porzucić tego odczytu IMAP' USING ERRCODE='23514';END IF;
  UPDATE public.email_inbound_acquisitions SET state='abandoned',updated_at=clock_timestamp() WHERE tenant_id=t AND id=ac.id;result:=jsonb_build_object('acquisition_id',ac.id);
 ELSIF ad.kind='import' THEN
  SELECT * INTO pv FROM public.email_inbound_previews WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF pv.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono podglądu' USING ERRCODE='P0002';END IF;
  IF(pv.actor_id,pv.api_key_id) IS DISTINCT FROM(ad.actor_id,ad.api_key_id) OR pv.expires_at<=clock_timestamp() OR b->>'scope_hash' IS DISTINCT FROM pv.scope_hash OR b->'confirmed' IS DISTINCT FROM 'true'::jsonb OR EXISTS(SELECT 1 FROM public.email_inbound_operations WHERE tenant_id=t AND kind='import' AND target_id=pv.id) THEN RAISE EXCEPTION 'Podgląd importu wymaga własnej świeżej zgody' USING ERRCODE='23514';END IF;
  SELECT * INTO a FROM public.email_inbound_accounts WHERE tenant_id=t AND id=pv.account_id FOR UPDATE;IF NOT a.enabled OR a.version::text IS DISTINCT FROM pv.payload->>'account_version' THEN RAISE EXCEPTION 'Konto zmieniło się przed importem' USING ERRCODE='23514';END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(pv.payload->'rows') LOOP
   SELECT * INTO s FROM public.email_inbound_sources WHERE tenant_id=t AND id=(x->>'source_id')::uuid;IF s.id IS NULL OR s.raw_sha256 IS DISTINCT FROM x->>'raw_sha256' THEN RAISE EXCEPTION 'Źródło importu zmieniło się' USING ERRCODE='23514';END IF;
   SELECT id INTO mid FROM public.email_inbound_messages WHERE tenant_id=t AND source_id=s.id;
   IF mid IS NULL THEN mid:=gen_random_uuid();INSERT INTO public.email_inbound_messages(id,tenant_id,source_id,account_id) VALUES(mid,t,s.id,a.id);new_count:=new_count+1;ELSE dup_count:=dup_count+1;END IF;rows_json:=rows_json||jsonb_build_array(mid);
  END LOOP;
  UPDATE public.email_inbound_accounts SET uidvalidity=pv.payload->>'uidvalidity',last_uid=nullif(pv.payload->>'scanned_through_uid','0'),version=version+1,updated_at=clock_timestamp() WHERE tenant_id=t AND id=a.id;
  result:=jsonb_build_object('import',jsonb_build_object('id',oid,'preview_id',pv.id,'message_ids',rows_json,'new_count',new_count,'duplicate_count',dup_count));
 ELSIF ad.kind='bind' THEN
  SELECT * INTO m FROM public.email_inbound_messages WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF m.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono wiadomości' USING ERRCODE='P0002';END IF;
  SELECT * INTO o FROM public.orders WHERE tenant_id=t AND id=(b->>'order_id')::uuid FOR UPDATE;
  IF m.state<>'unassigned' OR m.version::text IS DISTINCT FROM b->>'version' OR o.id IS NULL OR o.version::text IS DISTINCT FROM b->>'order_version' OR b->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Wiązanie wymaga świeżej wiadomości i zamówienia' USING ERRCODE='23514';END IF;
  SELECT * INTO cm FROM public.customer_messages WHERE tenant_id=t AND id=(b->>'core_message_id')::uuid;SELECT * INTO s FROM public.email_inbound_sources WHERE tenant_id=t AND id=m.source_id;
  IF cm.id IS NULL OR cm.kind<>'email' OR cm.actor_id<>ad.actor_id OR cm.order_id<>o.id OR cm.body IS DISTINCT FROM s.text_body THEN RAISE EXCEPTION 'Wiadomość wymaga rzeczywistej proweniencji email' USING ERRCODE='23514';END IF;
  entity:=(b->>'id')::uuid;INSERT INTO public.email_inbound_bindings(id,tenant_id,message_id,order_id,thread_id,core_message_id,order_version,actor_id,api_key_id) VALUES(entity,t,m.id,o.id,cm.thread_id,cm.id,o.version,ad.actor_id,ad.api_key_id);
  UPDATE public.email_inbound_messages SET state='bound',version=version+1,order_id=o.id,thread_id=cm.thread_id,core_message_id=cm.id,binding_id=entity WHERE tenant_id=t AND id=m.id;result:=jsonb_build_object('message_id',m.id,'binding_id',entity);
 ELSIF ad.kind='reply_preview' THEN
  SELECT * INTO m FROM public.email_inbound_messages WHERE tenant_id=t AND id=ad.target_id FOR SHARE;IF m.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono wiadomości' USING ERRCODE='P0002';END IF;
  SELECT * INTO o FROM public.orders WHERE tenant_id=t AND id=m.order_id FOR SHARE;SELECT * INTO s FROM public.email_inbound_sources WHERE tenant_id=t AND id=m.source_id;
  SELECT * INTO ch FROM public.channels WHERE tenant_id=t AND id=(b->'request'->>'smtp_channel_id')::uuid FOR SHARE;
  payload:=b->'snapshot';IF m.state<>'bound' OR m.version::text IS DISTINCT FROM b->'request'->>'version' OR o.version::text IS DISTINCT FROM b->'request'->>'order_version' OR ch.id IS NULL OR ch.provider<>'smtp' OR payload->>'smtp_channel_hash' IS DISTINCT FROM public.email_inbound_hash(jsonb_build_object('mode',ch.mode,'provider',ch.provider,'credentials',ch.credentials,'settings',ch.settings)) OR payload->'payload'->>'recipient' IS DISTINCT FROM lower(coalesce(s.headers->'reply_to'->>'address',s.headers->'from'->>'address')) THEN RAISE EXCEPTION 'Odpowiedź wymaga rzeczywistego adresata i świeżego źródła' USING ERRCODE='23514';END IF;
  IF payload->'order' IS DISTINCT FROM jsonb_build_object('id',o.id,'number',o.number,'version',o.version::text) OR payload->>'message_version' IS DISTINCT FROM m.version::text OR payload->>'smtp_channel_id' IS DISTINCT FROM ch.id::text OR payload->'sender' IS DISTINCT FROM jsonb_build_object('email',ch.settings->>'from_email','name',ch.settings->>'from_name','local_sink',coalesce(ch.settings->>'delivery','external')='local_sink') OR payload->'payload'->>'subject' IS DISTINCT FROM b->'request'->>'subject' OR payload->'payload'->>'text' IS DISTINCT FROM b->'request'->>'text' OR payload->'payload'->>'recipient' IS DISTINCT FROM b->'request'->>'recipient' OR payload->'payload'->'in_reply_to' IS DISTINCT FROM s.headers->'message_id' OR payload->'payload'->'references' IS DISTINCT FROM((s.headers->'references')||CASE WHEN s.headers->>'message_id' IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(s.headers->>'message_id') END) THEN RAISE EXCEPTION 'Odpowiedź wymaga dokładnego zamrożonego źródła' USING ERRCODE='23514';END IF;
  IF payload->'payload'->>'html' IS DISTINCT FROM('<p>'||replace(replace(replace(replace(replace(replace(b->'request'->>'text','&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),'''','&#39;'),chr(10),'<br>')||'</p>') OR char_length(b->'request'->>'text') NOT BETWEEN 1 AND 20000 OR char_length(b->'request'->>'subject') NOT BETWEEN 1 AND 200 OR b->'request'->>'subject'~'[\r\n]' THEN RAISE EXCEPTION 'Nieprawidłowa treść odpowiedzi' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(payload->'payload'->'references') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'payload'->'references')>101 OR coalesce((SELECT sum(char_length(value)+1) FROM jsonb_array_elements_text(payload->'payload'->'references')),0)+coalesce(char_length(payload->'payload'->>'in_reply_to'),0)>32768 THEN RAISE EXCEPTION 'Nieprawidłowy łańcuch odpowiedzi' USING ERRCODE='23514';END IF;
  entity:=(b->>'id')::uuid;INSERT INTO public.email_inbound_reply_previews(id,tenant_id,message_id,actor_id,api_key_id,client_key,request_hash,request,scope_hash,payload) VALUES(entity,t,m.id,ad.actor_id,ad.api_key_id,ck,h,b->'request',public.email_inbound_hash(payload),payload);result:=jsonb_build_object('reply_preview_id',entity);
 ELSIF ad.kind='reply_queue' THEN
  SELECT * INTO rp FROM public.email_inbound_reply_previews WHERE tenant_id=t AND id=ad.target_id FOR UPDATE;IF rp.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono podglądu odpowiedzi' USING ERRCODE='P0002';END IF;
  SELECT * INTO m FROM public.email_inbound_messages WHERE tenant_id=t AND id=rp.message_id FOR SHARE;SELECT * INTO o FROM public.orders WHERE tenant_id=t AND id=m.order_id FOR SHARE;SELECT * INTO ch FROM public.channels WHERE tenant_id=t AND id=(rp.payload->>'smtp_channel_id')::uuid FOR SHARE;
  IF(rp.actor_id,rp.api_key_id) IS DISTINCT FROM(ad.actor_id,ad.api_key_id) OR rp.expires_at<=clock_timestamp() OR b->'confirmed' IS DISTINCT FROM 'true'::jsonb OR b->>'scope_hash' IS DISTINCT FROM rp.scope_hash OR m.version::text IS DISTINCT FROM rp.payload->>'message_version' OR o.version::text IS DISTINCT FROM rp.payload->'order'->>'version' OR rp.payload->>'smtp_channel_hash' IS DISTINCT FROM public.email_inbound_hash(jsonb_build_object('mode',ch.mode,'provider',ch.provider,'credentials',ch.credentials,'settings',ch.settings)) THEN RAISE EXCEPTION 'Odpowiedź zmieniła się przed zgodą' USING ERRCODE='23514';END IF;
  IF coalesce(ch.settings->>'delivery','external')='external' AND(b->'confirm_external' IS DISTINCT FROM 'true'::jsonb OR(public.email_inbound_access(ad.actor_id,ad.api_key_id,true,false)->>'role') IS DISTINCT FROM 'admin') THEN RAISE EXCEPTION 'Zewnętrzna odpowiedź wymaga administratora i osobnej zgody' USING ERRCODE='23514';END IF;
  bid:=(b->>'batch_id')::uuid;eid:=(b->>'email_message_id')::uuid;jid:=(b->>'job_id')::uuid;entity:=(b->>'id')::uuid;
  INSERT INTO public.email_batches(id,tenant_id,actor_id,template_id,template_version,channel_id,channel_hash,mode,client_key,request_hash,state,external_allowed,inbound_reply_preview_id,inbound_api_key_id) VALUES(bid,t,ad.actor_id,NULL,NULL,ch.id,rp.payload->>'smtp_channel_hash','smtp',ck,h,'queued',(b->>'confirm_external')::boolean,rp.id,ad.api_key_id);
  INSERT INTO public.jobs(id,tenant_id,kind,payload,dedup_key,max_attempts) VALUES(jid,t,'email.send',jsonb_build_object('message_id',eid),'email:'||eid,1);
  INSERT INTO public.email_messages(id,tenant_id,batch_id,order_id,number,snapshot,payload,sender,state,job_id) VALUES(eid,t,bid,o.id,o.number,rp.payload,rp.payload->'payload',rp.payload->'sender','queued',jid);
  INSERT INTO public.email_inbound_replies(id,tenant_id,preview_id,message_id,batch_id,email_message_id,job_id,actor_id,api_key_id,client_key,request_hash,snapshot) VALUES(entity,t,rp.id,m.id,bid,eid,jid,ad.actor_id,ad.api_key_id,ck,h,to_jsonb(rp));result:=jsonb_build_object('reply_id',entity);
 END IF;
 INSERT INTO public.email_inbound_operations(id,tenant_id,actor_id,api_key_id,client_key,kind,target_id,request_hash,result) VALUES(oid,t,ad.actor_id,ad.api_key_id,ck,ad.kind,ad.target_id,h,result);PERFORM public.email_inbound_budget();RETURN result;
END $$;
-- Cleanup can only close the original in-flight attempt, including after permission withdrawal.
-- It cannot publish bytes or import, and always retains original actor/key identity.
CREATE FUNCTION email_inbound_abandon_fetch(rid uuid,uid uuid,kid uuid,error_code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;BEGIN
 PERFORM public.email_inbound_lock();IF error_code NOT IN('UNKNOWN','INVALID_MIME','UIDVALIDITY_CHANGED','ACCESS_CHANGED','SOURCE_CHANGED','TRANSPORT_FAILED') OR error_code IS NULL THEN RAISE EXCEPTION 'Nieprawidłowe zamknięcie odczytu' USING ERRCODE='23514';END IF;
 UPDATE public.email_inbound_acquisitions SET state=CASE WHEN email_inbound_abandon_fetch.error_code IN('INVALID_MIME','UIDVALIDITY_CHANGED') THEN 'failed' ELSE 'unknown' END,error_code=email_inbound_abandon_fetch.error_code,updated_at=clock_timestamp() WHERE tenant_id=t AND id=rid AND actor_id=uid AND api_key_id IS NOT DISTINCT FROM kid AND state='fetching';
END $$;
CREATE FUNCTION email_inbound_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$BEGIN RAISE EXCEPTION 'Historia odbioru email jest niezmienna' USING ERRCODE='23514';END $$;
CREATE FUNCTION email_inbound_row_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$DECLARE t uuid;rid uuid;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Historia odbioru email jest niezmienna' USING ERRCODE='23514';END IF;t:=NEW.tenant_id;rid:=NEW.id;
 -- Only SECURITY DEFINER writers own DML privileges. Accounts/messages transitions remain typed.
 IF TG_OP='UPDATE' THEN
 IF TG_TABLE_NAME='email_inbound_accounts' THEN IF ROW(NEW.id,NEW.tenant_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Konto wymaga CAS' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME='email_inbound_messages' THEN IF ROW(NEW.id,NEW.tenant_id,NEW.source_id,NEW.account_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.source_id,OLD.account_id,OLD.created_at) OR OLD.state<>'unassigned' OR NEW.state<>'bound' OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Wiązanie email jest niezmienne' USING ERRCODE='23514';END IF;
 ELSE IF ROW(NEW.id,NEW.tenant_id,NEW.account_id,NEW.actor_id,NEW.api_key_id,NEW.client_key,NEW.request_hash,NEW.request,NEW.account_version,NEW.config_hash,NEW.folder,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.account_id,OLD.actor_id,OLD.api_key_id,OLD.client_key,OLD.request_hash,OLD.request,OLD.account_version,OLD.config_hash,OLD.folder,OLD.created_at) OR OLD.state NOT IN('fetching','unknown','failed') OR NEW.state NOT IN('ready','unknown','failed','abandoned') THEN RAISE EXCEPTION 'Tożsamość odczytu IMAP jest niezmienna' USING ERRCODE='23514';END IF;END IF;
 END IF;RETURN NEW;
END $$;
CREATE FUNCTION email_inbound_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE ad public.email_inbound_admissions;op public.email_inbound_operations;m public.email_inbound_messages;r public.email_inbound_replies;cm public.customer_messages;BEGIN
 SELECT * INTO ad FROM public.email_inbound_admissions WHERE(tenant_id,operation_id)=(NEW.tenant_id,NEW.operation_id);SELECT * INTO op FROM public.email_inbound_operations WHERE(tenant_id,id)=(ad.tenant_id,ad.operation_id);
 IF op.id IS NULL OR ROW(op.actor_id,op.api_key_id,op.kind,op.target_id,op.client_key,op.request_hash) IS DISTINCT FROM ROW(ad.actor_id,ad.api_key_id,ad.kind,ad.target_id,ad.client_key,ad.request_hash) THEN RAISE EXCEPTION 'Operacja email wymaga pełnego pokwitowania' USING ERRCODE='23514';END IF;
 IF op.kind='bind' THEN SELECT * INTO m FROM public.email_inbound_messages WHERE(tenant_id,id)=(op.tenant_id,op.target_id);SELECT * INTO cm FROM public.customer_messages WHERE(tenant_id,id)=(m.tenant_id,m.core_message_id);IF m.state<>'bound' OR cm.kind IS DISTINCT FROM 'email' OR cm.order_id IS DISTINCT FROM m.order_id OR NOT EXISTS(SELECT 1 FROM public.email_inbound_bindings b WHERE(b.tenant_id,b.id,b.message_id,b.core_message_id)=(m.tenant_id,m.binding_id,m.id,cm.id)) THEN RAISE EXCEPTION 'Brak bijekcji źródła i wątku email' USING ERRCODE='23514';END IF;
 ELSIF op.kind='reply_queue' THEN SELECT * INTO r FROM public.email_inbound_replies WHERE tenant_id=op.tenant_id AND id=(op.result->>'reply_id')::uuid;IF r.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.email_batches b JOIN public.email_messages em ON(em.tenant_id,em.batch_id)=(b.tenant_id,b.id) JOIN public.jobs j ON(j.tenant_id,j.id)=(em.tenant_id,em.job_id) WHERE(b.tenant_id,b.id,em.id,j.id,b.inbound_reply_preview_id)=(r.tenant_id,r.batch_id,r.email_message_id,r.job_id,r.preview_id) AND em.payload=r.snapshot->'payload'->'payload' AND em.sender=r.snapshot->'payload'->'sender' AND b.actor_id=r.actor_id AND b.inbound_api_key_id IS NOT DISTINCT FROM r.api_key_id AND j.kind='email.send' AND j.payload=jsonb_build_object('message_id',em.id)) THEN RAISE EXCEPTION 'Odpowiedź wymaga pełnej bijekcji SMTP' USING ERRCODE='23514';END IF;END IF;
 PERFORM public.email_inbound_require(ad.actor_id,ad.api_key_id,true,false,ad.kind IN('account_create','account_update'));PERFORM public.email_inbound_budget();RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER email_inbound_complete AFTER INSERT ON email_inbound_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION email_inbound_complete();
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['email_inbound_accounts','email_inbound_acquisitions','email_inbound_messages'] LOOP EXECUTE format('CREATE TRIGGER email_inbound_row_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION email_inbound_row_guard()',rel);END LOOP;
 FOREACH rel IN ARRAY ARRAY['email_inbound_sources','email_inbound_previews','email_inbound_bindings','email_inbound_reply_previews','email_inbound_replies','email_inbound_operations','email_inbound_admissions'] LOOP EXECUTE format('CREATE TRIGGER email_inbound_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION email_inbound_immutable()',rel);END LOOP;END $$;
CREATE FUNCTION email_inbound_core_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE p public.email_inbound_reply_previews;BEGIN
 IF TG_TABLE_NAME='email_messages' THEN
  IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.email_batches b WHERE(b.tenant_id,b.id)=(OLD.tenant_id,OLD.batch_id) AND b.inbound_reply_preview_id IS NOT NULL) AND ROW(NEW.id,NEW.tenant_id,NEW.batch_id,NEW.job_id) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.batch_id,OLD.job_id) THEN RAISE EXCEPTION 'Graf odpowiedzi SMTP jest niezmienny' USING ERRCODE='23514';END IF;RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='customer_messages' THEN
  IF TG_OP='UPDATE' THEN IF OLD.kind='email' OR NEW.kind='email' THEN RAISE EXCEPTION 'Pochodzenie wiadomości email jest niezmienne' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
  IF NEW.kind='email' THEN IF TG_OP<>'INSERT' OR NOT EXISTS(SELECT 1 FROM public.email_inbound_admissions a WHERE(a.tenant_id,a.transaction_id,a.kind,a.actor_id)=(NEW.tenant_id,pg_current_xact_id(),'bind',NEW.actor_id)) THEN RAISE EXCEPTION 'Email wymaga bieżącej zgody wiązania' USING ERRCODE='23514';END IF;END IF;RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD.inbound_reply_preview_id IS NOT NULL AND(to_jsonb(NEW)-'state') IS DISTINCT FROM(to_jsonb(OLD)-'state') THEN RAISE EXCEPTION 'Pochodzenie odpowiedzi SMTP jest niezmienne' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.inbound_reply_preview_id,NEW.inbound_api_key_id) IS DISTINCT FROM ROW(OLD.inbound_reply_preview_id,OLD.inbound_api_key_id) THEN RAISE EXCEPTION 'Pochodzenie odpowiedzi jest niezmienne' USING ERRCODE='23514';END IF;
 IF NEW.inbound_reply_preview_id IS NOT NULL AND TG_OP='INSERT' THEN SELECT * INTO p FROM public.email_inbound_reply_previews WHERE(tenant_id,id)=(NEW.tenant_id,NEW.inbound_reply_preview_id);IF p.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.email_inbound_admissions a WHERE(a.tenant_id,a.transaction_id,a.kind,a.target_id,a.actor_id)=(NEW.tenant_id,pg_current_xact_id(),'reply_queue',p.id,NEW.actor_id) AND a.api_key_id IS NOT DISTINCT FROM NEW.inbound_api_key_id) THEN RAISE EXCEPTION 'Odpowiedź wymaga bieżącej zgody SMTP' USING ERRCODE='23514';END IF;END IF;RETURN NEW;
END $$;
CREATE TRIGGER email_inbound_core_guard BEFORE INSERT OR UPDATE ON customer_messages FOR EACH ROW EXECUTE FUNCTION email_inbound_core_guard();
CREATE TRIGGER email_inbound_core_guard BEFORE UPDATE ON email_messages FOR EACH ROW EXECUTE FUNCTION email_inbound_core_guard();
CREATE TRIGGER email_inbound_core_guard BEFORE INSERT OR UPDATE ON email_batches FOR EACH ROW EXECUTE FUNCTION email_inbound_core_guard();

CREATE FUNCTION email_inbound_core_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
 IF TG_TABLE_NAME='customer_messages' THEN
  IF NEW.kind='email' AND NOT EXISTS(SELECT 1 FROM public.email_inbound_bindings b JOIN public.email_inbound_messages m ON(m.tenant_id,m.id)=(b.tenant_id,b.message_id) JOIN public.email_inbound_sources s ON(s.tenant_id,s.id)=(m.tenant_id,m.source_id) JOIN public.email_inbound_admissions a ON(a.tenant_id,a.target_id,a.kind,a.transaction_id)=(m.tenant_id,m.id,'bind',pg_current_xact_id()) WHERE(b.tenant_id,b.core_message_id,b.order_id,b.thread_id,b.actor_id)=(NEW.tenant_id,NEW.id,NEW.order_id,NEW.thread_id,NEW.actor_id) AND b.api_key_id IS NOT DISTINCT FROM a.api_key_id AND a.actor_id=NEW.actor_id AND NEW.body=s.text_body) THEN RAISE EXCEPTION 'Brak dokładnej bijekcji wiadomości email i źródła' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME='email_batches' THEN
  IF NEW.inbound_reply_preview_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_inbound_replies r JOIN public.email_inbound_admissions a ON(a.tenant_id,a.target_id,a.kind,a.transaction_id)=(r.tenant_id,r.preview_id,'reply_queue',pg_current_xact_id()) WHERE(r.tenant_id,r.batch_id,r.preview_id,r.actor_id)=(NEW.tenant_id,NEW.id,NEW.inbound_reply_preview_id,NEW.actor_id) AND r.api_key_id IS NOT DISTINCT FROM NEW.inbound_api_key_id AND a.actor_id=r.actor_id AND a.api_key_id IS NOT DISTINCT FROM r.api_key_id) THEN RAISE EXCEPTION 'Brak dokładnej bijekcji partii odpowiedzi SMTP' USING ERRCODE='23514';END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM public.email_batches b WHERE(b.tenant_id,b.id)=(NEW.tenant_id,NEW.batch_id) AND b.inbound_reply_preview_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM public.email_inbound_replies r JOIN public.email_inbound_reply_previews p ON(p.tenant_id,p.id)=(r.tenant_id,r.preview_id) WHERE(r.tenant_id,r.email_message_id,r.batch_id,r.job_id)=(NEW.tenant_id,NEW.id,NEW.batch_id,NEW.job_id) AND NEW.snapshot=p.payload AND NEW.payload=p.payload->'payload' AND NEW.sender=p.payload->'sender' AND NEW.order_id=(p.payload->'order'->>'id')::uuid) THEN RAISE EXCEPTION 'Brak dokładnej bijekcji wiadomości SMTP' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER email_inbound_core_complete AFTER INSERT ON customer_messages DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION email_inbound_core_complete();
CREATE CONSTRAINT TRIGGER email_inbound_core_complete AFTER INSERT ON email_batches DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION email_inbound_core_complete();
CREATE CONSTRAINT TRIGGER email_inbound_core_complete AFTER INSERT ON email_messages DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION email_inbound_core_complete();
CREATE FUNCTION email_inbound_guards() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE rel text;guard_oid regclass;BEGIN
 FOREACH rel IN ARRAY ARRAY['email_inbound_accounts','email_inbound_acquisitions','email_inbound_sources','email_inbound_previews','email_inbound_messages','email_inbound_bindings','email_inbound_reply_previews','email_inbound_replies','email_inbound_operations','email_inbound_admissions'] LOOP guard_oid:=to_regclass('public.'||rel);IF guard_oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class WHERE pg_class.oid=guard_oid AND relrowsecurity AND relforcerowsecurity) OR has_table_privilege('dyna_app',guard_oid,'INSERT,UPDATE,DELETE,SELECT') OR has_any_column_privilege('dyna_app',guard_oid,'SELECT,INSERT,UPDATE,REFERENCES') OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=guard_oid AND NOT tgisinternal AND tgenabled='O' AND tgfoid=CASE WHEN rel IN('email_inbound_accounts','email_inbound_acquisitions','email_inbound_messages') THEN to_regprocedure('public.email_inbound_row_guard()') ELSE to_regprocedure('public.email_inbound_immutable()') END) THEN RETURN false;END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM(VALUES('email_inbound_accounts',2),('email_inbound_acquisitions',4),('email_inbound_sources',1),('email_inbound_previews',3),('email_inbound_messages',5),('email_inbound_bindings',5),('email_inbound_reply_previews',3),('email_inbound_replies',7),('email_inbound_operations',2),('email_inbound_admissions',1)) expected(rel,cnt) WHERE(SELECT count(*) FROM pg_constraint WHERE conrelid=to_regclass('public.'||expected.rel) AND contype='f' AND convalidated)<>expected.cnt) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['email_inbound_installed()','email_inbound_hash(jsonb)','email_inbound_access(uuid,uuid,boolean,boolean,boolean)','email_inbound_require(uuid,uuid,boolean,boolean,boolean)','email_inbound_lock()','email_inbound_account_head(email_inbound_accounts)','email_inbound_budget()','email_inbound_read(uuid,uuid,text,uuid,uuid,integer,jsonb)','email_inbound_begin(uuid,text,uuid,uuid,uuid,uuid,text)','email_inbound_store(uuid,uuid,text,jsonb)','email_inbound_abandon_fetch(uuid,uuid,uuid,text)','email_inbound_immutable()','email_inbound_row_guard()','email_inbound_complete()','email_inbound_core_guard()','email_inbound_core_complete()','email_inbound_import_reference(uuid,uuid,uuid)','email_inbound_reply_reference(uuid,uuid,uuid)','email_inbound_core_message_metadata(uuid,uuid,uuid)','email_inbound_worker_context(uuid,boolean)']) signatures(signature) WHERE to_regprocedure(signature) IS NULL) THEN RETURN false;END IF;
 RETURN EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass('public.email_inbound_admissions') AND tgfoid=to_regprocedure('public.email_inbound_complete()') AND tgenabled='O' AND tgdeferrable AND tginitdeferred) AND(SELECT count(*) FROM pg_trigger WHERE tgrelid IN(to_regclass('public.email_batches'),to_regclass('public.customer_messages'),to_regclass('public.email_messages')) AND tgfoid=to_regprocedure('public.email_inbound_core_guard()') AND tgenabled='O')=3 AND(SELECT count(*) FROM pg_trigger WHERE tgrelid IN(to_regclass('public.customer_messages'),to_regclass('public.email_batches'),to_regclass('public.email_messages')) AND tgfoid=to_regprocedure('public.email_inbound_core_complete()') AND tgenabled='O' AND tgdeferrable AND tginitdeferred)=3 AND NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid IN(SELECT c.oid FROM pg_class c WHERE c.relname LIKE 'email_inbound_%') AND NOT convalidated) AND EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=to_regclass('public.email_batches') AND attname='inbound_reply_preview_id' AND NOT attisdropped);
END $$;
CREATE FUNCTION email_inbound_require(uid uuid,kid uuid,writing boolean,pin boolean,manage boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE g jsonb;BEGIN
 IF NOT public.email_inbound_guards() OR NOT public.email_inbound_installed() THEN RAISE EXCEPTION 'Niekompletny odbiór email' USING ERRCODE='55000';END IF;
 g:=public.email_inbound_access(uid,kid,writing,pin,manage);IF g->'key_valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Klucz odbioru email jest nieaktualny' USING ERRCODE='23514';END IF;
 IF g->'allowed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Brak aktualnego uprawnienia odbioru email' USING ERRCODE='23514';END IF;RETURN g;
END $$;
CREATE FUNCTION email_inbound_lock() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('email-queue:'||current_setting('app.tenant_id'),0));PERFORM pg_advisory_xact_lock(hashtextextended('email-inbound:'||current_setting('app.tenant_id'),0));
END $$;
CREATE FUNCTION email_inbound_account_head(a public.email_inbound_accounts) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $$SELECT to_jsonb(a)-'credentials_encrypted'||jsonb_build_object('version',a.version::text,'has_credentials',a.credentials_encrypted IS NOT NULL)$$;
CREATE FUNCTION email_inbound_budget() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;n bigint;rel text;total bigint:=0;BEGIN
 IF(SELECT count(*) FROM public.email_inbound_accounts WHERE tenant_id=t)>20 OR(SELECT count(*) FROM public.email_inbound_messages WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM public.email_inbound_sources WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM public.email_inbound_acquisitions WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM public.email_inbound_previews WHERE tenant_id=t)>1000 OR(SELECT count(*) FROM public.email_inbound_reply_previews WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM public.email_inbound_operations WHERE tenant_id=t)>10000 THEN RAISE EXCEPTION 'Limit historii odbioru email' USING ERRCODE='23514';END IF;
 FOREACH rel IN ARRAY ARRAY['email_inbound_accounts','email_inbound_acquisitions','email_inbound_sources','email_inbound_previews','email_inbound_messages','email_inbound_bindings','email_inbound_reply_previews','email_inbound_replies','email_inbound_operations','email_inbound_admissions'] LOOP EXECUTE format('SELECT coalesce(sum(octet_length(to_jsonb(r)::text)),0) FROM public.%I r WHERE tenant_id=$1',rel) INTO n USING t;total:=total+n;END LOOP;
 IF total>134217728 THEN RAISE EXCEPTION 'Limit zaszyfrowanych danych odbioru email' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION email_inbound_read(uid uuid,kid uuid,op text,rid uuid DEFAULT NULL,cursor_id uuid DEFAULT NULL,lim integer DEFAULT 50,filter jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;result jsonb;a public.email_inbound_accounts;s public.email_inbound_sources;m public.email_inbound_messages;BEGIN
 PERFORM public.email_inbound_require(uid,kid,false,false);IF op IS NULL OR op NOT IN('accounts','account','transport','acquisitions','acquisition','preview','previews','message','messages','source_content','binding','reply_preview','reply','replies','operation','smtp') OR lim IS NULL OR lim NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Nieprawidłowy odczyt odbioru email' USING ERRCODE='23514';END IF;
 IF op IN('accounts','account','transport') THEN
  IF op='accounts' THEN SELECT coalesce(jsonb_agg(public.email_inbound_account_head(q) ORDER BY q.id),'[]') INTO result FROM public.email_inbound_accounts q WHERE q.tenant_id=t;RETURN jsonb_build_object('data',result,'next_cursor',NULL);END IF;
  SELECT * INTO a FROM public.email_inbound_accounts WHERE tenant_id=t AND id=rid;IF a.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono konta' USING ERRCODE='P0002';END IF;
  IF op='transport' THEN PERFORM public.email_inbound_require(uid,kid,true,false);IF NOT a.enabled OR a.credentials_encrypted IS NULL THEN RAISE EXCEPTION 'Konto IMAP jest wyłączone' USING ERRCODE='23514';END IF;RETURN to_jsonb(a)||jsonb_build_object('config_hash',public.email_inbound_hash(to_jsonb(a)-ARRAY['uidvalidity','last_uid','updated_at']));END IF;
  RETURN public.email_inbound_account_head(a);
 ELSIF op='smtp' THEN IF(SELECT count(*) FROM public.channels WHERE tenant_id=t AND provider='smtp')>100 THEN RAISE EXCEPTION 'Lista kont SMTP przekracza limit100' USING ERRCODE='23514';END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('id',ch.id,'name',ch.name,'mode',ch.mode,'delivery',coalesce(ch.settings->>'delivery','external')) ORDER BY ch.id),'[]') INTO result FROM public.channels ch WHERE tenant_id=t AND provider='smtp';RETURN result;
 ELSIF op='source_content' THEN SELECT * INTO s FROM public.email_inbound_sources WHERE tenant_id=t AND id=rid;IF s.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono źródła' USING ERRCODE='P0002';END IF;RETURN to_jsonb(s);
 ELSIF op IN('message','messages') THEN
  SELECT coalesce(jsonb_agg(q.row ORDER BY q.id),'[]') INTO result FROM(SELECT mm.id,to_jsonb(mm)||jsonb_build_object('version',mm.version::text,'uid',ss.uid,'uidvalidity',ss.uidvalidity,'headers',ss.headers,'text',CASE WHEN op='message' THEN ss.text_body ELSE NULL END,'attachments',ss.attachments,'raw_sha256',ss.raw_sha256,'raw_bytes',ss.raw_bytes) row FROM public.email_inbound_messages mm JOIN public.email_inbound_sources ss ON(ss.tenant_id,ss.id)=(mm.tenant_id,mm.source_id) WHERE mm.tenant_id=t AND(op<>'message' OR mm.id=rid) AND(op='message' OR(cursor_id IS NULL OR mm.id>cursor_id)) AND(op='message' OR filter->>'state' IS NULL OR mm.state=filter->>'state') AND(filter->>'account_id' IS NULL OR mm.account_id=(filter->>'account_id')::uuid) ORDER BY mm.id LIMIT CASE WHEN op='message' THEN 1 ELSE lim+1 END)q;
  IF op='message' THEN IF jsonb_array_length(result)=0 THEN RAISE EXCEPTION 'Nie znaleziono wiadomości' USING ERRCODE='P0002';END IF;RETURN result->0;END IF;
 ELSIF op='previews' THEN SELECT coalesce(jsonb_agg(q.row ORDER BY q.id),'[]') INTO result FROM(SELECT p.id,jsonb_build_object('id',p.id,'acquisition_id',p.acquisition_id,'account_id',p.account_id,'scope_hash',p.scope_hash,'summary',p.payload->'summary','created_at',p.created_at,'expires_at',p.expires_at) row FROM public.email_inbound_previews p WHERE p.tenant_id=t AND(cursor_id IS NULL OR p.id>cursor_id) AND(filter->>'account_id' IS NULL OR p.account_id=(filter->>'account_id')::uuid) ORDER BY p.id LIMIT lim+1)q;
 ELSIF op IN('acquisitions','replies') THEN
  IF op='acquisitions' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO result FROM(SELECT * FROM public.email_inbound_acquisitions WHERE tenant_id=t AND(cursor_id IS NULL OR id>cursor_id) AND(filter->>'account_id' IS NULL OR account_id=(filter->>'account_id')::uuid) ORDER BY id LIMIT lim+1)q;
  ELSE SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO result FROM(SELECT * FROM public.email_inbound_replies WHERE tenant_id=t AND(cursor_id IS NULL OR id>cursor_id) AND(filter->>'message_id' IS NULL OR message_id=(filter->>'message_id')::uuid) ORDER BY id LIMIT lim+1)q;END IF;
 ELSIF op='acquisition' THEN SELECT to_jsonb(q) INTO result FROM public.email_inbound_acquisitions q WHERE tenant_id=t AND id=rid;
 ELSIF op='preview' THEN SELECT to_jsonb(q) INTO result FROM public.email_inbound_previews q WHERE tenant_id=t AND id=rid;
 ELSIF op='binding' THEN SELECT to_jsonb(q) INTO result FROM public.email_inbound_bindings q WHERE tenant_id=t AND id=rid;
 ELSIF op='reply_preview' THEN SELECT to_jsonb(q) INTO result FROM public.email_inbound_reply_previews q WHERE tenant_id=t AND id=rid;
 ELSIF op='reply' THEN SELECT to_jsonb(q) INTO result FROM public.email_inbound_replies q WHERE tenant_id=t AND id=rid;
 ELSE SELECT to_jsonb(q) INTO result FROM public.email_inbound_operations q WHERE tenant_id=t AND id=rid;END IF;
 IF op IN('messages','acquisitions','replies','previews') THEN RETURN jsonb_build_object('data',(SELECT coalesce(jsonb_agg(v ORDER BY n),'[]') FROM jsonb_array_elements(result) WITH ORDINALITY z(v,n) WHERE n<=lim),'next_cursor',CASE WHEN jsonb_array_length(result)>lim THEN result->(lim-1)->>'id' ELSE NULL END);END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'Nie znaleziono własnego wyniku' USING ERRCODE='P0002';END IF;RETURN result;
END $$;
CREATE FUNCTION email_inbound_import_reference(rid uuid,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE answer uuid;BEGIN PERFORM public.email_inbound_require(uid,kid,false,false);SELECT id INTO answer FROM public.email_inbound_operations WHERE tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND kind='import' AND target_id=rid;RETURN answer;END $$;
CREATE FUNCTION email_inbound_reply_reference(rid uuid,uid uuid,kid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE answer uuid;BEGIN PERFORM public.email_inbound_require(uid,kid,false,false);SELECT id INTO answer FROM public.email_inbound_replies WHERE tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND preview_id=rid;RETURN answer;END $$;
CREATE FUNCTION email_inbound_core_message_metadata(rid uuid,uid uuid,kid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE answer jsonb;BEGIN PERFORM public.email_inbound_require(uid,kid,false,false);SELECT jsonb_build_object('message_id',m.id,'account_id',m.account_id,'from',s.headers->'from','subject',s.headers->>'subject','raw_sha256',s.raw_sha256) INTO answer FROM public.email_inbound_messages m JOIN public.email_inbound_sources s ON(s.tenant_id,s.id)=(m.tenant_id,m.source_id) WHERE m.tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND m.core_message_id=rid;RETURN answer;END $$;
CREATE FUNCTION email_inbound_worker_context(eid uuid,pin boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;em public.email_messages;b public.email_batches;r public.email_inbound_replies;p public.email_inbound_reply_previews;o public.orders;ch public.channels;g jsonb;BEGIN
 SELECT * INTO em FROM public.email_messages WHERE tenant_id=t AND id=eid;SELECT * INTO b FROM public.email_batches WHERE tenant_id=t AND id=em.batch_id;SELECT * INTO r FROM public.email_inbound_replies WHERE tenant_id=t AND email_message_id=eid;SELECT * INTO p FROM public.email_inbound_reply_previews WHERE tenant_id=t AND id=b.inbound_reply_preview_id;
 IF em.id IS NULL OR p.id IS NULL OR r.id IS NULL OR ROW(r.preview_id,r.batch_id,r.job_id,r.actor_id,r.api_key_id) IS DISTINCT FROM ROW(p.id,b.id,em.job_id,b.actor_id,b.inbound_api_key_id) OR em.payload IS DISTINCT FROM p.payload->'payload' OR em.sender IS DISTINCT FROM p.payload->'sender' OR em.snapshot IS DISTINCT FROM p.payload OR em.order_id IS DISTINCT FROM(p.payload->'order'->>'id')::uuid OR b.mode<>'smtp' OR b.channel_id IS DISTINCT FROM(p.payload->>'smtp_channel_id')::uuid OR b.channel_hash IS DISTINCT FROM p.payload->>'smtp_channel_hash' OR b.template_id IS NOT NULL THEN RAISE EXCEPTION 'Brak niezmiennego źródła odpowiedzi SMTP' USING ERRCODE='23514';END IF;
 SELECT * INTO o FROM public.orders WHERE tenant_id=t AND id=em.order_id FOR SHARE;SELECT * INTO ch FROM public.channels WHERE tenant_id=t AND id=b.channel_id FOR SHARE;
 IF o.id IS NULL OR o.version::text IS DISTINCT FROM p.payload->'order'->>'version' OR ch.id IS NULL OR ch.provider<>'smtp' OR b.channel_hash IS DISTINCT FROM public.email_inbound_hash(jsonb_build_object('mode',ch.mode,'provider',ch.provider,'credentials',ch.credentials,'settings',ch.settings)) THEN RAISE EXCEPTION 'Źródło odpowiedzi SMTP zmieniło się' USING ERRCODE='23514';END IF;
 g:=public.email_inbound_require(b.actor_id,b.inbound_api_key_id,true,pin);
 IF g->'can_order_read' IS DISTINCT FROM 'true'::jsonb OR(coalesce(ch.settings->>'delivery','external')='external' AND(g->>'role'<>'admin' OR NOT b.external_allowed)) THEN RAISE EXCEPTION 'Brak aktualnego uprawnienia odbioru email' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('actor_id',b.actor_id,'api_key_id',b.inbound_api_key_id,'role',g->>'role','snapshot',p.payload);
END $$;
DO $$DECLARE fn record;BEGIN FOR fn IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'email_inbound_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,dyna_app',fn.signature);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION email_inbound_installed(),email_inbound_guards(),email_inbound_hash(jsonb),email_inbound_access(uuid,uuid,boolean,boolean,boolean),email_inbound_lock(),email_inbound_read(uuid,uuid,text,uuid,uuid,integer,jsonb),email_inbound_begin(uuid,text,uuid,uuid,uuid,uuid,text),email_inbound_store(uuid,uuid,text,jsonb),email_inbound_abandon_fetch(uuid,uuid,uuid,text),email_inbound_import_reference(uuid,uuid,uuid),email_inbound_reply_reference(uuid,uuid,uuid),email_inbound_core_message_metadata(uuid,uuid,uuid),email_inbound_worker_context(uuid,boolean) TO dyna_app;
